<script setup lang="ts">import { onMounted, ref } from 'vue'; import axios from 'axios'; import api from '../plugins/axios'; const rows=ref<any[]>([]); const error=ref(''); const desde=new Date().toISOString().slice(0,10); const hasta=new Date(Date.now()+6*86400000).toISOString().slice(0,10); async function cargar(){try{rows.value=(await api.get('/capacidad',{params:{desde,hasta}})).data}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo cargar la capacidad.':'No se pudo cargar la capacidad.'}} async function guardar(row:any){try{await api.put(`/capacidad/${row.fecha}`,{puntosLimite:Number(row.puntosLimite)});await cargar()}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo actualizar.':'No se pudo actualizar.'}} onMounted(cargar)</script>
<template><section class="container py-5"><h1 class="h2 fw-bold mb-4">Capacidad diaria</h1><div v-if="error" class="alert alert-danger">{{ error }}</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Usados</th><th>Disponibles</th><th>Límite</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.fecha"><td>{{ row.fecha }}</td><td>{{ row.puntosUsados }}</td><td>{{ row.puntosDisponibles }}</td><td><input v-model="row.puntosLimite" class="form-control" type="number" min="0" /></td><td><button class="btn btn-sm btn-primary" type="button" @click="guardar(row)">Guardar</button></td></tr></tbody></table></div></section></template>
